import sys
from array import array

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it); q = next(it)
    parent = array('i', range(n + 1))
    size = array('i', [1]) * (n + 1)
    left = array('i', range(n + 1))
    right = array('i', range(n + 1))
    color = array('i', range(n + 1))
    count = array('i', [0]) * (n + 1)
    for i in range(1, n + 1):
        count[i] = 1

    def find(x):
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != x:
            y = parent[x]
            parent[x] = r
            x = y
        return r

    def union(a, b):
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    out = []
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            x = next(it); c = next(it)
            r = find(x)
            old = color[r]
            if old != c:
                length = size[r]
                count[old] -= length
                count[c] += length
                color[r] = c
                while left[r] > 1:
                    t = find(left[r] - 1)
                    if color[t] != c:
                        break
                    r = union(r, t)
                while right[r] < n:
                    t = find(right[r] + 1)
                    if color[t] != c:
                        break
                    r = union(r, t)
        else:
            c = next(it)
            out.append(str(count[c]))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

