from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, i))

        max_a = second_a = 0
        max_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for a, idx in ending[r]:
                if a > max_a:
                    second_a = max_a
                    max_a = a
                    max_id = idx
                elif a > second_a:
                    second_a = a

            # Of the starts 1..r, those greater than max_a are valid.
            total += r - max_a

            # Removing the unique pair attaining max_a relaxes the bound
            # to second_a, gaining max_a - second_a subarrays at this r.
            if max_id != -1 and max_a > second_a:
                gains[max_id] += max_a - second_a

        return total + max(gains)

