N = A * B - 1

# This exhaustive implementation is only practical for very small N.
def lis_len(seq):
    tails = []
    import bisect
    for x in seq:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

ans = 0
for p in permutations(range(1, N + 1)):
    if lis_len(p) != A or lis_len([-x for x in p]) != B:
        continue
    good = False
    for n in range(N + 1):
        q = p + (n + 0.5,)
        if lis_len(q) == A and lis_len([-x for x in q]) == B:
            good = True
            break
    ans += good
print(ans % M)

