import sys
import math


def main():
    input = sys.stdin.readline
    n, budget = map(int, input().split())
    processes = [tuple(map(int, input().split())) for _ in range(n)]

    def minimum_cost(target, process):
        a, p, b, q = process
        g = math.gcd(a, b)
        best = 10**30

        # If S is no cheaper per unit of capacity, reduce its count
        # modulo b/g by exchanging equal-capacity groups for T machines.
        if p * b >= q * a:
            for x in range(b // g):
                remaining = target - a * x
                y = (remaining + b - 1) // b if remaining > 0 else 0
                best = min(best, p * x + q * y)
        else:
            # Symmetrically, the number of T machines can be bounded by a/g.
            for y in range(a // g):
                remaining = target - b * y
                x = (remaining + a - 1) // a if remaining > 0 else 0
                best = min(best, q * y + p * x)
        return best

    def feasible(target):
        total = 0
        for process in processes:
            total += minimum_cost(target, process)
            if total > budget:
                return False
        return True

    # Capacity cannot exceed budget * 100, since every machine costs at
    # least 1 and processes at most 100 products per day.
    low, high = 0, 10**9 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

