MOD=10**9+7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        # Factorials let us count fixed-popcount suffixes in O(1).
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (n + 1)
        invfact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        # If x has c set bits, its first reduction gives c. Thus x is
        # k-reducible exactly when c reaches 1 in at most k-1 more steps.
        valid_counts = []
        for c in range(1, n + 1):
            value = c
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                valid_counts.append(c)

        answer = 0
        for target_ones in valid_counts:
            ones_left = target_ones
            for i, bit in enumerate(s):
                if bit == '1':
                    # Choose 0 here to become smaller, then place the
                    # remaining required ones in the suffix.
                    answer += comb(n - i - 1, ones_left)
                    if answer >= MOD:
                        answer -= MOD
                    ones_left -= 1
                    if ones_left < 0:
                        break

        return answer % MOD

