import sys
from collections import deque

def main():
    input=sys.stdin.buffer.readline
    n=int(input())
    g=[input().strip().decode() for _ in range(n)]
    inc=[[[] for _ in range(26)] for _ in range(n)]
    out=[[[] for _ in range(26)] for _ in range(n)]
    edges=[]
    for u in range(n):
        for v,ch in enumerate(g[u]):
            if ch!= '-':
                c=ord(ch)-97
                out[u][c].append(v)
                inc[v][c].append(u)
                edges.append((u,v))
    d=[[-1]*n for _ in range(n)]
    q=deque()
    for i in range(n):
        d[i][i]=0
        q.append((i,i))
    for u,v in edges:
        if d[u][v]<0:
            d[u][v]=1
            q.append((u,v))
    while q:
        x,y=q.popleft()
        nd=d[x][y]+2
        for c in range(26):
            a=inc[x][c]
            b=out[y][c]
            if a and b:
                for u in a:
                    du=d[u]
                    for v in b:
                        if du[v]<0:
                            du[v]=nd
                            q.append((u,v))
    print('\n'.join(' '.join(map(str,row)) for row in d))
if __name__=='__main__': main()

