import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    rows = [0] * n
    for _ in range(m):
        u = next(it) - 1
        v = next(it) - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    pivots = []
    r = 0
    for c in range(n):
        p = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if p is None:
            continue
        rows[r], rows[p] = rows[p], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free_columns = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free_columns:
        vec = 1 << f
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        basis.append(vec)

    # Assign a separate binary digit to each kernel basis vector.
    # Leave room within the permitted 60-bit positive range.
    shift = 2 if m > 0 and len(basis) <= 58 else 0
    values = [0] * n
    for j, vec in enumerate(basis):
        digit = 1 << (j + shift)
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= digit

    if any(value == 0 for value in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

