from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2

        def completions(o: int, e: int, prev: int) -> int:
            m = o + e
            if m == 0:
                return 1
            starts = (0, 1) if prev == -1 else (1 - prev,)
            total = 0
            for first in starts:
                count_o = (m + (1 if first == 1 else 0)) // 2
                count_e = m - count_o
                if count_o == o and count_e == e:
                    total += factorial(o) * factorial(e)
            return total

        if completions(odds, evens, -1) < k:
            return []

        available = list(range(1, n + 1))
        out = []
        o, e, prev = odds, evens, -1

        for _ in range(n):
            for x in available:
                parity = x & 1
                if prev != -1 and parity == prev:
                    continue

                next_o = o - (parity == 1)
                next_e = e - (parity == 0)
                ways = completions(next_o, next_e, parity)

                if k > ways:
                    k -= ways
                else:
                    out.append(x)
                    available.remove(x)
                    o, e, prev = next_o, next_e, parity
                    break
            else:
                return []

        return out

