class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = [0] * m
        for t in range(m):
            j = n - 1 - t
            coeff[t] = powers[t] if t == j else (powers[t] + powers[j]) % k

        # suffix[t][r] indicates that positions t..m-1 can contribute r mod k.
        suffix = [None] * (m + 1)
        suffix[m] = bytearray([1] + [0] * (k - 1))
        for t in range(m - 1, 0, -1):
            nxt = suffix[t + 1]
            cur = bytearray(k)
            c = coeff[t]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        cur[(r + d * c) % k] = 1
            suffix[t] = cur

        digits = []
        needed = 0
        for d in range(9, 0, -1):
            rem = (-d * coeff[0]) % k
            if suffix[1][rem]:
                digits.append(str(d))
                needed = rem
                break

        for t in range(1, m):
            for d in range(9, -1, -1):
                rem = (needed - d * coeff[t]) % k
                if suffix[t + 1][rem]:
                    digits.append(str(d))
                    needed = rem
                    break

        half = ''.join(digits)
        return half + (half[-2::-1] if n % 2 else half[::-1])

