    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        ans=0
        for left in range(n):
            mx=nums[left]
            cost=0
            for right in range(left,n):
                if nums[right] < mx:
                    cost += mx-nums[right]
                else:
