from typing import List
from collections import deque
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        q=deque()
        cost=ans=right=0
        a=nums[::-1]
        for x in a:
            cnt=1
            while q and q[0][0] <= x:
                v,c=q.popleft()
                cost += (x-v)*c
                cnt += c
            q.appendleft((x,cnt))
            while cost>k:
                v,c=q[-1]
                if c==1:q.pop()
                else:q[-1]=(v,c-1)
                right+=1
            ans += len(a)-right # wrong windows counted? current window length i-right+1
        return ans

