class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        f = [0] * 26
        for ch in s:
            f[ord(ch) - 97] += 1
        # For a fixed common frequency k, process the alphabet from left to
        # right.  carry is the number of letters changed from the previous
        # character into this one.  At each character choose whether its
        # final frequency is zero or k, and how many letters to change onward.
        ans = len(s)
        m = max(f)
        for k in range(1, m + 1):
            # A carry greater than k can never help: at most k letters can be
            # retained at any destination, and any surplus is cheaper to delete.
            dp = {0: 0}
            for i in range(26):
                ndp = {}
                for carry, cost in dp.items():
                    available = f[i] + carry
                    for want in (0, k):
                        # outgoing letters are a subset of the available
                        # letters. Unused letters are deleted; deficits inserted.
                        upper = min(available, k)
                        for out in range(upper + 1):
                            here = out + abs(available - out - want)
                            v = cost + here
                            if v < ndp.get(out, 10**9):
                                ndp[out] = v
                dp = ndp
            ans = min(ans, min(dp.values()))
        return ans

