class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                    pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                    if j == m:
                        out.append(i - m + 1)
                        j = pi[j - 1]
            return out

        oa, ob, oc = occurrences(a), occurrences(b), occurrences(c)
        ai = bi = 0
        latest_a = None
        ans = n + 1
        for cs in oc:
            while bi < len(ob) and ob[bi] + len(b) <= cs:
                bs = ob[bi]
                while ai < len(oa) and oa[ai] + len(a) <= bs:
                    latest_a = oa[ai]
                    ai += 1
                bi += 1
            if latest_a is not None:
                ans = min(ans, cs + len(c) - latest_a)
        return -1 if ans == n + 1 else ans

