import sys

def feasible(a, b, d):
    m = len(a)
    n = len(b)
    if n > m:
        return False

    # Match every required target to a distinct source, in order.
    j = 0
    for x in a:
        if j < n and abs(x - b[j]) <= d:
            j += 1
    if j < n:
        return False

    # Every remaining source must be able to end at some occupied target.
    j = 0
    for x in a:
        while j + 1 < n and abs(x - b[j + 1]) <= abs(x - b[j]):
            j += 1
        if abs(x - b[j]) > d:
            return False
    return True

def solve(a_str, b_str):
    a = [i for i, c in enumerate(a_str) if c == '1']
    b = [i for i, c in enumerate(b_str) if c == '1']
    if len(a) < len(b):
        return -1
    lo, hi = 0, len(a_str)
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(a, b, mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

