class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        # Best totals ending with A or B in each of the two preceding hours.
        a2 = b2 = 0
        a1, b1 = energyDrinkA[0], energyDrinkB[0]

        for i in range(1, n):
            if i == 1:
                # A switch cannot yet have occurred: hour 0 was consumed.
                a = a1 + energyDrinkA[i]
                b = b1 + energyDrinkB[i]
            else:
                # To switch to this drink at i, the other drink was consumed
                # at i-2, with hour i-1 left for cleansing.
                a = max(a1 + energyDrinkA[i], b2 + energyDrinkA[i])
                b = max(b1 + energyDrinkB[i], a2 + energyDrinkB[i])
            a2, b2 = a1, b1
            a1, b1 = a, b

        return max(a1, b1)

