        mins = [None] * k
        mins[0] = 0
        prefix = 0
        best = None
        for j, x in enumerate(nums, 1):
            prefix += x
            r = j % k
            if mins[r] is not None:
                value = prefix - mins[r]
                if best is None or value > best:
                    best = value
            if mins[r] is None or prefix < mins[r]:
                mins[r] = prefix
        return best

