class Solution:
    def countPairs(self, nums: List[int]) -> int:
        answer = 0
        for i in range(len(nums)):
            a = str(nums[i])
            for j in range(i):
                b = str(nums[j])
                length = max(len(a), len(b))
                x = a.zfill(length)
                y = b.zfill(length)

                differing = [k for k in range(length) if x[k] != y[k]]
                if not differing:
                    answer += 1
                elif len(differing) == 2:
                    p, q = differing
                    if x[p] == y[q] and x[q] == y[p]:
                        answer += 1
        return answer

