from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s is set iff sum s can be formed for this index so far.
        reachable = [1] * n  # Initially only sum 0 is possible.

        if all(value == 0 for value in nums):
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                reachable[i] |= reachable[i] << value
                # Sums above nums[i] can never contribute to a solution.
                reachable[i] &= (1 << (nums[i] + 1)) - 1

            if all((reachable[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

