class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10 ** len(str(n))
        prime = bytearray(b'\x01') * limit
        prime[0] = 0
        if limit > 1:
            prime[1] = 0
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = b'\x00' * (((limit - 1 - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        inf = 10**30
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            # Only digits in the current ordinary decimal representation are
            # editable; in particular, a leading zero is not retained.
            for i in range(len(str(x))):
                place = 10**i
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))
                if digit > 0:
                    y = x - place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))

        return -1

