from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] = LCP(nums, nums[i:]); this tests whether the first
        # subarray is a prefix of the second.
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        answer = 0
        # Let i be the first cut and k the length of the second subarray.
        # For each i, a Z-array on nums[i:] tests whether the second
        # subarray is a prefix of the third.
        for i in range(1, n - 1):
            m = n - i
            local_z = [0] * m
            left = right = 0
            first_is_prefix = z[i] >= i

            for k in range(1, m):
                if k <= right:
                    local_z[k] = min(right - k + 1, local_z[k - left])
                while (k + local_z[k] < m and
                       nums[i + local_z[k]] == nums[i + k + local_z[k]]):
                    local_z[k] += 1
                if k + local_z[k] - 1 > right:
                    left, right = k, k + local_z[k] - 1

                # The first condition also requires the second subarray
                # to be at least as long as the first (k >= i).
                if (first_is_prefix and k >= i) or local_z[k] >= k:
                    answer += 1

        return answer

