from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        removable = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            # Each transition uses the states from before processing source[i].
            ndp = dp[:]  # keep this character without matching it
            if i in removable:
                for j, value in enumerate(dp):
                    if value != neg and value + 1 > ndp[j]:
                        ndp[j] = value + 1
            for j in range(m):
                if ch == pattern[j] and dp[j] > ndp[j + 1]:
                    ndp[j + 1] = dp[j]
            dp = ndp

        return dp[m]

