class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j
        ones = s.count('1')
        best = 0
        zero_lengths = [length for bit, length in runs if bit == '0']
        for k, (bit, length) in enumerate(runs):
            if bit == '1' and 0 < k < len(runs) - 1:
                left = runs[k - 1][1]
                right = runs[k + 1][1]
                other = max((z for z in zero_lengths if z != left or False), default=0)
                # Exclude the two neighboring zero runs by run index, not length.
                other = max((runs[q][1] for q in range(1, len(runs), 2) if q != k - 1 and q != k + 1), default=0)
                best = max(best, left + right - length, other - length)
        return ones + max(0, best)

